INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'nature', 'n.', '/ˈneɪtʃə(r)/', '自然;大自然;本性', 'We should learn to live in harmony with nature.', '我们应该学会与大自然和谐相处。', 'Nature', 1, 0, 'senior', 'wordlist', 'required2', 'U1', 'the balance of nature', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'native', 'adj.', '/ˈneɪtɪv/', '原产于某地的;土生的;当地的', 'These flowers are native to this part of the world.', '这些花原产于世界的这一带。', 'Nature', 2, 0, 'senior', 'wordlist', 'required2', 'U1', 'native plants', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rare', 'adj.', '/reə(r)/', '稀有的;珍贵的;稀少的', 'Many rare plants only grow in this forest.', '许多稀有植物只生长在这片森林里。', 'Nature', 3, 0, 'senior', 'wordlist', 'required2', 'U1', 'a rare species', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'insect', 'n.', '/ˈɪnsekt/', '昆虫', 'Tiny insects help the flowers grow in the garden.', '小昆虫帮助花园里的花生长。', 'Nature', 4, 0, 'senior', 'wordlist', 'required2', 'U1', 'tiny insects', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'balance', 'n.', '/ˈbæləns/', '平衡;均衡;均势', 'Every creature plays a part in the balance of nature.', '每一种生物都在自然的平衡中发挥作用。', 'Nature', 5, 0, 'senior', 'wordlist', 'required2', 'U1', 'keep the balance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'destroy', 'v.', '/dɪˈstrɔɪ/', '摧毁;毁灭;破坏', 'People should not destroy the homes of wild animals.', '人们不应该破坏野生动物的家园。', 'Nature', 6, 0, 'senior', 'wordlist', 'required2', 'U1', 'destroy the forest', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'delicate', 'adj.', '/ˈdelɪkət/', '易损的;脆弱的;精巧的', 'The balance of nature is delicate and easy to break.', '自然的平衡很脆弱,容易被打破。', 'Nature', 7, 0, 'senior', 'wordlist', 'required2', 'U1', 'a delicate balance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'damage', 'v./n.', '/ˈdæmɪdʒ/', '损害;破坏;损坏', 'We are damaging the natural world far too fast.', '我们破坏自然界的速度太快了。', 'Nature', 8, 0, 'senior', 'wordlist', 'required2', 'U1', 'damage the environment', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'beyond', 'prep.', '/bɪˈjɒnd/', '超出;在……较远的一边', 'Some damage to nature may soon be beyond repair.', '对自然的某些破坏可能很快就无法修复了。', 'Nature', 9, 0, 'senior', 'wordlist', 'required2', 'U1', 'beyond repair', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'generation', 'n.', '/ˌdʒenəˈreɪʃn/', '一代人;一代', 'We must protect nature for future generations.', '我们必须为子孙后代保护大自然。', 'Nature', 10, 0, 'senior', 'wordlist', 'required2', 'U1', 'future generations', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'preserve', 'v.', '/prɪˈzɜːv/', '保护;保存;维护', 'It is our duty to preserve wild forests and rivers.', '保护原始森林和河流是我们的责任。', 'Nature', 11, 0, 'senior', 'wordlist', 'required2', 'U1', 'preserve nature', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'appreciate', 'v.', '/əˈpriːʃieɪt/', '欣赏;重视;领会;感激', 'Learn to appreciate the beauty all around us in nature.', '学会欣赏我们身边大自然的美。', 'Nature', 12, 0, 'senior', 'wordlist', 'required2', 'U1', 'appreciate the beauty', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'transform', 'v.', '/trænsˈfɔːm/', '使改变形态;使转变', 'Snow can transform a familiar landscape into a white wonderland.', '雪能把熟悉的景色变成银白的仙境。', 'Nature', 13, 0, 'senior', 'wordlist', 'required2', 'U1', 'transform the landscape', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'familiar', 'adj.', '/fəˈmɪliə(r)/', '熟悉的;通晓的;常见的', 'The hill near my home is a familiar sight to me.', '我家附近的小山对我来说是熟悉的景象。', 'Nature', 14, 0, 'senior', 'wordlist', 'required2', 'U1', 'a familiar view', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'landscape', 'n.', '/ˈlændskeɪp/', '风景;景色;乡村风景画', 'The painter loved to draw the landscape of the countryside.', '这位画家喜欢画乡村的风景。', 'Nature', 15, 0, 'senior', 'wordlist', 'required2', 'U1', 'a beautiful landscape', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'affect', 'v.', '/əˈfekt/', '影响;对……产生作用', 'The weather can deeply affect the way we feel.', '天气会深深影响我们的感受。', 'Nature', 16, 0, 'senior', 'wordlist', 'required2', 'U1', 'affect our moods', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'mood', 'n.', '/muːd/', '情绪;心情', 'A sunny morning often puts me in a good mood.', '阳光明媚的早晨常让我心情很好。', 'Nature', 17, 0, 'senior', 'wordlist', 'required2', 'U1', 'a cheerful mood', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'responsible', 'adj.', '/rɪˈspɒnsəbl/', '作为原因的;有责任的;负责的', 'Nature is responsible for the sun, rain and snow.', '自然带来了阳光、雨水和雪。', 'Nature', 18, 0, 'senior', 'wordlist', 'required2', 'U1', 'be responsible for', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'romantic', 'adj.', '/rəʊˈmæntɪk/', '浪漫的;富有情调的;美妙的', 'The moonlight over the lake made the night feel romantic.', '湖面上的月光让这个夜晚显得很浪漫。', 'Nature', 19, 0, 'senior', 'wordlist', 'required2', 'U1', 'a romantic night', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'frozen', 'adj.', '/ˈfrəʊzn/', '冻硬的;冰冻的;冷冻的', 'In spring a small flower pushes through the frozen ground.', '春天里,一朵小花从冻硬的土地中钻出。', 'Nature', 20, 0, 'senior', 'wordlist', 'required2', 'U1', 'the frozen ground', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'aware', 'adj.', '/əˈweə(r)/', '知道的;意识到的;明白的', 'Becoming more aware of nature can change our lives.', '更多地留意自然能够改变我们的生活。', 'Nature', 21, 0, 'senior', 'wordlist', 'required2', 'U1', 'be aware of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'positive', 'adj.', '/ˈpɒzətɪv/', '积极的;乐观的;自信的', 'Time in nature has a positive effect on our minds.', '亲近自然对我们的心灵有积极的影响。', 'Nature', 22, 0, 'senior', 'wordlist', 'required2', 'U1', 'a positive effect', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cruel', 'adj.', '/ˈkruːəl/', '残酷的;残忍的;引起痛苦的', 'Some people think it is cruel to keep animals in cages.', '有些人认为把动物关在笼子里很残忍。', 'Nature', 23, 0, 'senior', 'wordlist', 'required2', 'U1', 'cruel to animals', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'debate', 'v./n.', '/dɪˈbeɪt/', '讨论;辩论;争论', 'We often debate whether zoos are good for animals.', '我们常常争论动物园对动物是否有益。', 'Nature', 24, 0, 'senior', 'wordlist', 'required2', 'U1', 'debate the issue', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'establishment', 'n.', '/ɪˈstæblɪʃmənt/', '机构;大型机关;企业', 'Many people do not support these establishments at all.', '许多人根本不支持这些机构。', 'Nature', 25, 0, 'senior', 'wordlist', 'required2', 'U1', 'support the establishment', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'welfare', 'n.', '/ˈwelfeə(r)/', '幸福;福祉;安康', 'Animal welfare is a growing concern in our society.', '动物福利在我们的社会中越来越受关注。', 'Nature', 26, 0, 'senior', 'wordlist', 'required2', 'U1', 'animal welfare', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'concern', 'n.', '/kənˈsɜːn/', '担心;忧虑;关切', 'The future of wild tigers is a serious concern.', '野生老虎的未来令人深感忧虑。', 'Nature', 27, 0, 'senior', 'wordlist', 'required2', 'U1', 'a growing concern', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'argue', 'v.', '/ˈɑːɡjuː/', '论证;主张;争辩', 'Some people argue that zoos are cruel to animals.', '有些人认为动物园对动物很残忍。', 'Nature', 28, 0, 'senior', 'wordlist', 'required2', 'U1', 'argue that', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'remove', 'v.', '/rɪˈmuːv/', '移开;拿走;去除', 'It is wrong to remove animals from their natural homes.', '把动物从它们的自然家园中带走是不对的。', 'Nature', 29, 0, 'senior', 'wordlist', 'required2', 'U1', 'remove animals from', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'habitat', 'n.', '/ˈhæbɪtæt/', '生活环境;栖息地', 'Each animal has its own natural habitat in the wild.', '每种动物在野外都有自己的天然栖息地。', 'Nature', 30, 0, 'senior', 'wordlist', 'required2', 'U1', 'natural habitat', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cage', 'n.', '/keɪdʒ/', '笼子', 'A bird kept in a cage cannot fly freely.', '关在笼子里的鸟不能自由飞翔。', 'Nature', 31, 0, 'senior', 'wordlist', 'required2', 'U1', 'kept in a cage', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'hunt', 'v.', '/hʌnt/', '打猎;猎取;搜寻', 'Wild animals must hunt for food every single day.', '野生动物每天都必须觅食。', 'Nature', 32, 0, 'senior', 'wordlist', 'required2', 'U1', 'hunt for food', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'additionally', 'adv.', '/əˈdɪʃənəli/', '另外;此外', 'Additionally, some animals become unhappy in small spaces.', '此外,有些动物在狭小的空间里会变得不快乐。', 'Nature', 33, 0, 'senior', 'wordlist', 'required2', 'U1', 'additionally, ...', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'exhibit', 'v.', '/ɪɡˈzɪbɪt/', '展览;展出;表现出', 'Zoos exhibit animals from all over the world.', '动物园展出来自世界各地的动物。', 'Nature', 34, 0, 'senior', 'wordlist', 'required2', 'U1', 'exhibit animals', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'adjust', 'v.', '/əˈdʒʌst/', '适应;调整;调节', 'Animals must adjust to different climates and seasons.', '动物必须适应不同的气候和季节。', 'Nature', 35, 0, 'senior', 'wordlist', 'required2', 'U1', 'adjust to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'climate', 'n.', '/ˈklaɪmət/', '气候', 'Some plants only flourish in a warm and wet climate.', '有些植物只在温暖潮湿的气候中茁壮生长。', 'Nature', 36, 0, 'senior', 'wordlist', 'required2', 'U1', 'a warm climate', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'location', 'n.', '/ləʊˈkeɪʃn/', '地点;位置;场所', 'The zoo''s location decides which animals can live there.', '动物园的位置决定了哪些动物能在那里生活。', 'Nature', 37, 0, 'senior', 'wordlist', 'required2', 'U1', 'a perfect location', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'design', 'v./n.', '/dɪˈzaɪn/', '设计;构思;意欲', 'Workers design the park to look like a real habitat.', '工人们把公园设计得像真正的栖息地。', 'Nature', 38, 0, 'senior', 'wordlist', 'required2', 'U1', 'design a park', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'extinction', 'n.', '/ɪkˈstɪŋkʃn/', '灭绝;绝种;消亡', 'Many rare animals are now close to extinction.', '许多稀有动物如今濒临灭绝。', 'Nature', 39, 0, 'senior', 'wordlist', 'required2', 'U1', 'save from extinction', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'conservation', 'n.', '/ˌkɒnsəˈveɪʃn/', '(对自然环境的)保护', 'Conservation helps to keep the whole ecosystem healthy.', '环境保护有助于保持整个生态系统的健康。', 'Nature', 40, 0, 'senior', 'wordlist', 'required2', 'U1', 'wildlife conservation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'essential', 'adj.', '/ɪˈsenʃl/', '必不可少的;极其重要的', 'Clean water is essential for every living thing.', '清洁的水对每一个生物都必不可少。', 'Nature', 41, 0, 'senior', 'wordlist', 'required2', 'U1', 'an essential part', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'threat', 'n.', '/θret/', '威胁;构成威胁的事物', 'Pollution is a serious threat to wild plants and animals.', '污染对野生动植物构成严重威胁。', 'Nature', 42, 0, 'senior', 'wordlist', 'required2', 'U1', 'a threat to nature', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'particularly', 'adv.', '/pəˈtɪkjələli/', '特别;尤其', 'These trees grow particularly well in warm valleys.', '这些树在温暖的山谷里长得特别好。', 'Nature', 43, 0, 'senior', 'wordlist', 'required2', 'U1', 'particularly important', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'exist', 'v.', '/ɪɡˈzɪst/', '存在;生存', 'Thousands of species exist together in this forest.', '成千上万的物种共同生存在这片森林里。', 'Nature', 44, 0, 'senior', 'wordlist', 'required2', 'U1', 'exist in nature', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'species', 'n.', '/ˈspiːʃiːz/', '物种;种类', 'Losing one species can put many others in danger.', '失去一个物种会让许多其他物种陷入危险。', 'Nature', 45, 0, 'senior', 'wordlist', 'required2', 'U1', 'different species', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'restore', 'v.', '/rɪˈstɔː(r)/', '恢复;修复;使复原', 'It takes many years to restore the balance of nature.', '恢复自然的平衡需要很多年。', 'Nature', 46, 0, 'senior', 'wordlist', 'required2', 'U1', 'restore nature', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u1.01', '①who / whom(指人)', 'A2', 10, '上外版必修第二册 U1 — 先行词指人:从句缺主语用 who;从句缺宾语用 whom(口语/非正式也可 who),不可用 which。', 1, 'required2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u1.02', '②which / that(指物)', 'A2', 10, '上外版必修第二册 U1 — 先行词指物(限制性定语从句):缺主语或宾语用 which 或 that,不可用 who/whose。', 2, 'required2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u1.03', '③whose(所属)· 介词 + which / whom', 'A2', 10, '上外版必修第二册 U1 — 表所属关系(……的)用 whose + 名词,指人指物皆可;关系词作介词宾语提前时,指物用「介词+which」、指人用「介词+whom」,介词后不可用 that。', 3, 'required2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U1' AND code='s2u1.01'), 'The young man ____ explained the mystery had grown up near the king''s gardens.', 'who', 'which', 'whose', 'where', 'A', '先行词 man 指人、从句缺主语 → who。', 2, 1, 'mcq');
